import{_ as o,c as e,o as a,ag as r}from"./chunks/framework.3IuuWm4t.js";const b=JSON.parse('{"title":"博客园配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/metaweblog-cnblogs.md","filePath":"platforms/metaweblog-cnblogs.md","lastUpdated":1795809563000}'),l={name:"platforms/metaweblog-cnblogs.md"};function d(n,t,i,s,c,h){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="博客园配置指南" tabindex="-1">博客园配置指南 <a class="header-anchor" href="#博客园配置指南" aria-label="Permalink to &quot;博客园配置指南&quot;">​</a></h1><blockquote><p>TODO：待替换真实帮助文档链接（当前 helpUrl 指向的短链需用户确认）。</p></blockquote><p>博客园通过 <strong>MetaWeblog XML-RPC</strong> 发布。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个博客园账号。</li><li>一个 <strong>API Token</strong>（不是登录密码！）。</li></ol><h2 id="二、获取-api-token" tabindex="-1">二、获取 API Token <a class="header-anchor" href="#二、获取-api-token" aria-label="Permalink to &quot;二、获取 API Token&quot;">​</a></h2><ol><li>登录博客园后台 → 设置 → 开放 API（或「开放接口」）。</li><li>生成并复制 Token。</li></ol><h2 id="三、在插件里配置" tabindex="-1">三、在插件里配置 <a class="header-anchor" href="#三、在插件里配置" aria-label="Permalink to &quot;三、在插件里配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>你的博客首页，如 <code>https://www.cnblogs.com/你的用户名</code></td></tr><tr><td>API 地址</td><td><code>https://rpc.cnblogs.com/metaweblog/你的博客名</code></td></tr><tr><td>用户名</td><td>博客园登录用户名</td></tr><tr><td>鉴权 Token</td><td>上面生成的 <strong>API Token</strong>（不是登录密码）</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/[userid]/p/[postid].html</code></td></tr><tr><td>发布格式</td><td>默认 Markdown</td></tr><tr><td>图床</td><td>默认「当前平台」（博客园内置）；需要时可选「PicGo 强烈推荐」</td></tr></tbody></table><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证并保存」，通过后账号状态变「运行中」。</li><li>快速发布 → 选博客园 → 发布。</li></ol><h2 id="五、选择发布类型与草稿" tabindex="-1">五、选择发布类型与草稿 <a class="header-anchor" href="#五、选择发布类型与草稿" aria-label="Permalink to &quot;五、选择发布类型与草稿&quot;">​</a></h2><p>2.4.0 修复了发布类型和草稿选项不生效的问题：所选内容类型会正确应用，草稿不会被直接公开发布。</p><ul><li><strong>发布类型</strong>：在详细发布页的「文章分类」中选择 <code>[发布为文章]</code>、<code>[发布为日记]</code> 或 <code>[发布为新闻]</code>，发布到对应类型。</li><li><strong>发布至博客园首页</strong>：<code>[发布至博客园首页]</code> 仅适用于随笔，请勿与文章、日记或新闻类型同时选择。</li><li><strong>保存草稿</strong>：在「文章状态」选择「草稿」后发布或更新。需要公开时，再将状态改为「发布」并更新文章。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>提示「用户名或密码错误」</strong>：确认用的是 API Token 而非登录密码。</li><li><strong>图片上传失败</strong>：默认「当前平台」即可（博客园内置）；需要时可选「PicGo 强烈推荐」并先在设置里配置好 PicGo。</li><li><strong>发布到了随笔而不是文章</strong>：请升级至 2.4.0，并在详细发布页的「文章分类」中选择所需发布类型。<code>[发布至博客园首页]</code> 只适用于随笔，不能与文章/日记/新闻同时选择。</li><li><strong>选了草稿却直接发布</strong>：发布页「文章状态」选择「草稿」会存为草稿，只有选择「发布」才会公开。</li></ul>',16)])])}const p=o(l,[["render",d]]);export{b as __pageData,p as default};
